namespace T {
  interface Readonly {
    ...
  }

  interface ReadWrite {
    ...
  }

  function create(): ReadWrite {
    ...
  }
}

namespace Graph {
  interface Readonly {
    vertex: ReadonlySet;
    edge: (v0: Value) => (v1: Value) => ReadonlySet;
  }

  interface ReadWrite extends Readonly {
    vertex: ReadWriteSet;
    edge: (v0: Value) => (v1: Value) => ReadWriteSet;
  }

  function create(): ReadWrite {
    ...
  }
}

namespace BagOfGraphs {
  interface Readonly {
    graph_id: ReadonlySet;
    graph_for: (i : Value) => Graph.Readonly;
  }

  interface ReadWrite extends Readonly {
    graph_id: ReadWriteSet;
    graph_for: (i : Value) => Graph.ReadWrite;
  }

  function create(): ReadWrite {
    ...
  }
}

const g0 = Graph.create()
const bog = BagOfGraphs.create()
const g1_id = bog.graph_id.add()
const g1 = bog.graph_for(g1_id)

const RowId = {
  from: DatabaseId,
  index: number
}

const Value =
  { tag: "row_id", value: RowId } |
  { tag: "tuple", value: Record<string, Value> } |
  { tag: "int", value: number } |
  { tag: "string", value: string }

interface ReadonlySet {
  has(x: Value): boolean;
  values(): Iterator<Value>;
}

interface ReadWriteSet extends ReadonlySet {
  add(): Value;
}

const alice = m.nice.add()
const bob = m.naughty.add()
assert(m.nice.has(alice))
assert(!m.nice.has(bob))

interface ReadonlyProp {
  isTrue(): boolean;
}

interface ReadWriteProp extends ReadonlyProp {
  makeTrue(): void;
}

const john = m.children.add()
const y2025 = m.year.add()
const y2026 = m.year.add()
m.list(y2025).nice(john).makeTrue()
m.list(y2026).naughty(john).makeTrue()

def list-for (m : SantaLists) (y : m.year) : SantaList := struct
  naughty := tuple { child : m.person; m.list y .naughty child }
  nice := tuple { child : m.person; m.list y .nice child }
end
